const color_icon_t *color_icon_for_logo(int16_t logo_idx)
{
    switch (logo_idx) {
        case RG_LOGO_PAD_NES: return &cicon_nes;
        case RG_LOGO_PAD_GB: return &cicon_gb;
        case RG_LOGO_PAD_GBC: return &cicon_gbc;
        case RG_LOGO_PAD_GG: return &cicon_gg;
        case RG_LOGO_PAD_SMS: return &cicon_sms;
        case RG_LOGO_PAD_GEN: return &cicon_md;
        case RG_LOGO_PAD_SG1000: return &cicon_sg;
        case RG_LOGO_PAD_COL: return &cicon_col;
        case RG_LOGO_PAD_PCE: return &cicon_pce;
        case RG_LOGO_PAD_PCECD: return &cicon_pcecd;
        case RG_LOGO_PAD_MSX: return &cicon_msx;
        case RG_LOGO_PAD_WSV: return &cicon_wsv;
        case RG_LOGO_PAD_WSWAN: return &cicon_ws;
        case RG_LOGO_PAD_NGP: return &cicon_ngp;
        case RG_LOGO_PAD_A2600: return &cicon_a2600;
        case RG_LOGO_PAD_A7800: return &cicon_a7800;
        case RG_LOGO_PAD_LYNX: return &cicon_lynx;
        case RG_LOGO_PAD_AMSTRAD: return &cicon_amstrad;
        case RG_LOGO_PAD_TAMA: return &cicon_tama;
        case RG_LOGO_PAD_PKMINI: return &cicon_mini;
        case RG_LOGO_PAD_GW: return &cicon_gw;
        case RG_LOGO_PAD_PICO8: return &cicon_pico8;
        case RG_LOGO_PAD_HOMEBREW: return &cicon_homebrew;
        case RG_LOGO_PAD_VIDEOPAC: return &cicon_videopac;
        case RG_LOGO_PAD_ZX: return &cicon_zxs;
        case RG_LOGO_PAD_C64: return &cicon_c64;
        case RG_LOGO_PAD_GAMECOM: return &cicon_gamecom;
        case RG_LOGO_PAD_VB: return &cicon_vb;
        case RG_LOGO_PAD_GBA: return &cicon_gba;
        case RG_LOGO_PAD_SNES: return &cicon_snes;
        case RG_LOGO_PAD_32X: return &cicon_32x;
        /* Upstream's rg_favorites.c registers the tab with
         * RG_LOGO_HEADER_FAVORITES in gui_add_tab()'s logo_idx slot, so that is
         * the index this override has to answer -- otherwise the draw falls
         * through to rg_get_logo() and the player gets upstream's monochrome
         * star instead of this fork's colour one. Upstream's asset stays
         * defined and keeps its index; we just override what gets drawn.
         * RG_LOGO_PAD_FAVORITES is kept for any caller still using it. */
        case RG_LOGO_HEADER_FAVORITES:
        case RG_LOGO_PAD_FAVORITES: return &cicon_favorites;
        default: return (const color_icon_t *)0;
    }
}
